# the r779-r780 chain is deduped to one.
PATH = "scripts/r781_close.sh"
with open(PATH) as f:
    lines = f.readlines()

start = next(i for i, l in enumerate(lines) if l.startswith("L.append('Agent:"))
end = next(i for i, l in enumerate(lines) if l.startswith("L.append('Blockers:"))

q0 = next(i for i, l in enumerate(lines) if l.startswith("L.append('- QA PROBES"))
q1 = next(i for i, l in enumerate(lines) if l.startswith("L.append('- GATES:"))
env_block = [lines[q0]]
for l in lines[q0 + 1 : q1 + 1]:
    if l.startswith("L.append('- QA PROBES"):
        continue
    env_block.append(l)

